tool_args.command:
python3 -c "
import json, os, glob

base = '/home/ubuntu/.agent-ml-research-idea_gen_0519_2/projects/cert_manip_resist_eval/scoring/results/plan001/individual_scores/'
files = glob.glob(os.path.join(base, '*.json'))

results = {}
for f in sorted(files):
    name = os.path.basename(f).replace('.json','')
    parts = name.split('__')
    if len(parts) == 3:
        model, ds, cond = parts
    else:
        continue
    with open(f) as fh:
        d = json.load(fh)

    if model not in results:
        results[model] = {}

    key = f'{ds}__{cond}'
    if cond == 'clean':
        results[model][key] = {'acc': d.get('accuracy'), 'errors': d.get('n_errors',0)}
    else:
        results[model][key] = {'asr': d.get('asr'), 'errors': d.get('n_errors',0)}

# Print summary table
print(f'{'Model':<25} {'Clean ACC (mmlu/arc)':>20} {'Max ASR':>10} {'Max Errors':>12}')
print('-'*70)
for m in sorted(results):
    mmlu_acc = results[m].get('mmlu__clean',{}).get('acc','?')
    arc_acc = results[m].get('arc_challenge__clean',{}).get('acc','?')

    max_asr = 0
    max_err = 0
    for k,v in results[m].items():
        if 'asr' in v and v['asr'] is not None:
            max_asr = max(max_asr, v['asr'])
        max_err = max(max_err, v.get('errors',0))

    acc_str = f'{mmlu_acc:.3f}/{arc_acc:.3f}' if isinstance(mmlu_acc,float) and isinstance(arc_acc,float) else f'{mmlu_acc}/{arc_acc}'
    print(f'{m:<25} {acc_str:>20} {max_asr:>10.4f} {max_err:>12}')
" 2>/dev/null
